from collections import Counter

def transform(grid):
    """Fill enclosed regions with color 4"""
    result = [row[:] for row in grid]

    # Get background color (most common)
    all_cells = []
    for r in range(len(grid)):
        for c in range(len(grid[r])):
            all_cells.append(grid[r][c])
    background = Counter(all_cells).most_common(1)[0][0]

    # Flood fill from edges to find boundary-reachable cells
    rows, cols = len(grid), len(grid[0])
    boundary_reachable = set()
    queue = []

    for r in range(rows):
        if grid[r][0] == background:
            boundary_reachable.add((r, 0))
            queue.append((r, 0))
        if grid[r][cols-1] == background:
            boundary_reachable.add((r, cols-1))
            queue.append((r, cols-1))
    for c in range(1, cols-1):
        if grid[0][c] == background:
            boundary_reachable.add((0, c))
            queue.append((0, c))
        if grid[rows-1][c] == background:
            boundary_reachable.add((rows-1, c))
            queue.append((rows-1, c))

    head = 0
    while head < len(queue):
        r, c = queue[head]
        head += 1
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if (nr, nc) not in boundary_reachable and grid[nr][nc] == background:
                    boundary_reachable.add((nr, nc))
                    queue.append((nr, nc))

    fill_color = 4

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == background and (r, c) not in boundary_reachable:
                result[r][c] = fill_color

    return result

